import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel for diag_matmul: out[i,j] = A[i] * B[i,j]
kernel_source = """
__global__ void diag_matmul_kernel(const float* a_diag, const float* b, float* out, int N, int M) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * M) {
        int i = idx / M; // row index
        int j = idx % M; // column index
        out[idx] = a_diag[i] * b[idx];
    }
}
"""

# Function to be compiled:
function_source = """
torch::Tensor diag_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    const float* a_ptr = A.data_ptr<float>();
    const float* b_ptr = B.data_ptr<float>();
    float* out_ptr = torch::empty_like(B); // need to allocate? We'll create zeros.

    int N = static_cast<int>(A.size());
    int M = static_cast<int>(B.size(1));
    auto out = torch::zeros_like(B);

    const int block_size = 256;
    const int num_blocks = (N * M + block_size - 1) / block_size;

    diag_matmul_kernel<<<num_blocks, block_size>>>(a_ptr, b_ptr, out.data_ptr<float()>, N, M);

    return out;
}
"""

# C++ source for function signature
cpp_source = "torch::Tensor diag_matmul_cuda(torch::Tensor A, torch::Tensor B);"

